export const docsContentHtml =
  '<h1>Special markup</h1>\n<p>Most Ionic markup works without changes. The combinations below are explicit opt-ins and are useful when the same template also uses <code>@rdlabo/ionic-theme-ios26</code>.</p>\n<h2>Two-line inset list items</h2>\n<p>Place an unslotted <code>ion-label</code> immediately alongside an unslotted <code>ion-note</code> to render a two-line item. Use <code>slot=&quot;end&quot;</code> on <code>ion-note</code> when you want the standard trailing-note layout instead.</p>\n<div class="code-block-container"><pre class="shiki github-dark" style="background-color:#151e2c;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#E1E4E8">&#x3C;</span><span style="color:#85E89D">ion-list</span><span style="color:#B392F0"> inset</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"true"</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">  &#x3C;</span><span style="color:#85E89D">ion-item-group</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">    &#x3C;</span><span style="color:#85E89D">ion-item</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">      &#x3C;</span><span style="color:#85E89D">ion-label</span><span style="color:#E1E4E8">>Network </span><span style="color:#79B8FF">&#x26;amp;</span><span style="color:#E1E4E8"> internet&#x3C;/</span><span style="color:#85E89D">ion-label</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">      &#x3C;</span><span style="color:#85E89D">ion-note</span><span style="color:#E1E4E8">>Mobile, Wi-Fi, hotspot&#x3C;/</span><span style="color:#85E89D">ion-note</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">    &#x3C;/</span><span style="color:#85E89D">ion-item</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">  &#x3C;/</span><span style="color:#85E89D">ion-item-group</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">&#x3C;/</span><span style="color:#85E89D">ion-list</span><span style="color:#E1E4E8">></span></span></code></pre></div>\n\n<figure class="docs-example">\n<figcaption>Preview</figcaption>\n<ion-list inset="true">\n  <ion-item-group>\n    <ion-item>\n      <ion-label>Network &amp; internet</ion-label>\n      <ion-note>Mobile, Wi-Fi, hotspot</ion-note>\n    </ion-item>\n  </ion-item-group>\n</ion-list>\n</figure>\n\n<h2>Square buttons</h2>\n<p>Add <code>.button-square</code> when a button should use more squared corners. It works with text buttons and icon-only buttons.</p>\n<div class="code-block-container"><pre class="shiki github-dark" style="background-color:#151e2c;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#E1E4E8">&#x3C;</span><span style="color:#85E89D">ion-button</span><span style="color:#B392F0"> class</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"button-square"</span><span style="color:#B392F0"> fill</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"solid"</span><span style="color:#E1E4E8">>Continue&#x3C;/</span><span style="color:#85E89D">ion-button</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">&#x3C;</span><span style="color:#85E89D">ion-button</span><span style="color:#B392F0"> class</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"button-square"</span><span style="color:#B392F0"> fill</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"solid"</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">  &#x3C;</span><span style="color:#85E89D">ion-icon</span><span style="color:#B392F0"> name</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"add"</span><span style="color:#B392F0"> slot</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"icon-only"</span><span style="color:#E1E4E8">>&#x3C;/</span><span style="color:#85E89D">ion-icon</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">&#x3C;/</span><span style="color:#85E89D">ion-button</span><span style="color:#E1E4E8">></span></span></code></pre></div>\n\n<figure class="docs-example">\n<figcaption>Preview</figcaption>\n<ion-button class="button-square" fill="solid">Continue</ion-button>\n<ion-button class="button-square" fill="solid">\n  <ion-icon name="add" slot="icon-only"></ion-icon>\n</ion-button>\n</figure>\n\n<h2>Inset-list section headers</h2>\n<p>Add <code>.item-group-header</code> to an <code>ion-item-group</code> to create the centered icon, title, and description used at the top of the component demo pages.</p>\n<p>This is an introductory group. Place regular list items in a separate <code>ion-item-group</code> that follows it.</p>\n<div class="code-block-container"><pre class="shiki github-dark" style="background-color:#151e2c;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#E1E4E8">&#x3C;</span><span style="color:#85E89D">ion-list</span><span style="color:#B392F0"> inset</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"true"</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">  &#x3C;</span><span style="color:#85E89D">ion-item-group</span><span style="color:#B392F0"> class</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"item-group-header"</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">    &#x3C;</span><span style="color:#85E89D">ion-item</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">      &#x3C;</span><span style="color:#85E89D">ion-label</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">        &#x3C;</span><span style="color:#85E89D">ion-icon</span><span style="color:#B392F0"> name</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"list"</span><span style="color:#B392F0"> style</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"background: var(--ion-color-primary)"</span><span style="color:#E1E4E8">>&#x3C;/</span><span style="color:#85E89D">ion-icon</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">        &#x3C;</span><span style="color:#85E89D">h2</span><span style="color:#E1E4E8">>Lists&#x3C;/</span><span style="color:#85E89D">h2</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">        &#x3C;</span><span style="color:#85E89D">ion-text</span><span style="color:#E1E4E8">>Inset-list examples&#x3C;/</span><span style="color:#85E89D">ion-text</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">      &#x3C;/</span><span style="color:#85E89D">ion-label</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">    &#x3C;/</span><span style="color:#85E89D">ion-item</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">  &#x3C;/</span><span style="color:#85E89D">ion-item-group</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">  &#x3C;</span><span style="color:#85E89D">ion-item-group</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">    &#x3C;</span><span style="color:#85E89D">ion-item</span><span style="color:#E1E4E8">>&#x3C;</span><span style="color:#85E89D">ion-label</span><span style="color:#E1E4E8">>First item&#x3C;/</span><span style="color:#85E89D">ion-label</span><span style="color:#E1E4E8">>&#x3C;/</span><span style="color:#85E89D">ion-item</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">  &#x3C;/</span><span style="color:#85E89D">ion-item-group</span><span style="color:#E1E4E8">></span></span>\n<span class="line"><span style="color:#E1E4E8">&#x3C;/</span><span style="color:#85E89D">ion-list</span><span style="color:#E1E4E8">></span></span></code></pre></div>\n\n<figure class="docs-example">\n<figcaption>Preview</figcaption>\n<ion-list inset="true">\n  <ion-item-group class="item-group-header">\n    <ion-item>\n      <ion-label>\n        <ion-icon name="list" style="background: var(--ion-color-primary)"></ion-icon>\n        <h2>Lists</h2>\n        <ion-text>Inset-list examples</ion-text>\n      </ion-label>\n    </ion-item>\n  </ion-item-group>\n  <ion-item-group>\n    <ion-item><ion-label>First item</ion-label></ion-item>\n  </ion-item-group>\n</ion-list>\n</figure>\n\n<h2>Opting out</h2>\n<p>Add <code>.md3-disabled</code> to an individual Ionic component when it must retain Ionic&#39;s standard Material styling.</p>\n<div class="code-block-container"><pre class="shiki github-dark" style="background-color:#151e2c;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#E1E4E8">&#x3C;</span><span style="color:#85E89D">ion-button</span><span style="color:#B392F0"> fill</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"solid"</span><span style="color:#E1E4E8">>MD3 theme&#x3C;/</span><span style="color:#85E89D">ion-button</span><span style="color:#E1E4E8">> &#x3C;</span><span style="color:#85E89D">ion-button</span><span style="color:#B392F0"> class</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"md3-disabled"</span><span style="color:#B392F0"> fill</span><span style="color:#E1E4E8">=</span><span style="color:#9ECBFF">"solid"</span><span style="color:#E1E4E8">>Standard Ionic&#x3C;/</span><span style="color:#85E89D">ion-button</span><span style="color:#E1E4E8">></span></span></code></pre></div>\n\n<figure class="docs-example">\n<figcaption>Preview</figcaption>\n<ion-button fill="solid">MD3 theme</ion-button> <ion-button class="md3-disabled" fill="solid">Standard Ionic</ion-button>\n</figure>\n';
